-- RPBS v7: additive handover controls; existing rows are preserved.
CREATE TABLE IF NOT EXISTS audit_events (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id INT NULL, actor_name VARCHAR(255) NULL,
 actor_role VARCHAR(30) NULL, unit_id INT NULL, action VARCHAR(40) NOT NULL,
 entity_type VARCHAR(60) NOT NULL, entity_id BIGINT NOT NULL,
 before_data LONGTEXT NULL, after_data LONGTEXT NULL, request_id VARCHAR(64) NULL,
 client_ip VARCHAR(45) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
 KEY idx_audit_time(created_at,id), KEY idx_audit_entity(entity_type,entity_id), KEY idx_audit_unit(unit_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS mutation_requests (
 request_key VARCHAR(48) PRIMARY KEY, user_id INT NOT NULL, action_path VARCHAR(255) NOT NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS fiscal_periods (
 unit_id INT NOT NULL, fiscal_year INT NOT NULL, period_month TINYINT NOT NULL,
 closed TINYINT(1) NOT NULL DEFAULT 0, closed_at DATETIME NULL, closed_by INT NULL,
 reason VARCHAR(255) NULL, summary_json LONGTEXT NULL,
 PRIMARY KEY(unit_id,fiscal_year,period_month)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS document_snapshots (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, document_type VARCHAR(40) NOT NULL,
 document_id INT NOT NULL DEFAULT 0, unit_id INT NOT NULL, fiscal_year INT NOT NULL,
 filename VARCHAR(255) NOT NULL, content_type VARCHAR(100) NOT NULL,
 sha256 CHAR(64) NOT NULL, payload LONGBLOB NOT NULL, metadata_json LONGTEXT NOT NULL,
 created_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uniq_snapshot(document_type,document_id,sha256), KEY idx_snapshot_unit(unit_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS system_contacts (
 id INT PRIMARY KEY, primary_name VARCHAR(255) NOT NULL DEFAULT '',
 primary_position VARCHAR(255) NOT NULL DEFAULT '', primary_contact VARCHAR(255) NOT NULL DEFAULT '',
 backup_name VARCHAR(255) NOT NULL DEFAULT '', backup_position VARCHAR(255) NOT NULL DEFAULT '',
 backup_contact VARCHAR(255) NOT NULL DEFAULT '', it_contact VARCHAR(255) NOT NULL DEFAULT '',
 updated_by INT NULL, updated_at DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL, client_ip VARCHAR(45) NOT NULL,
 successful TINYINT(1) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_login_limit(client_ip,created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS reservation_releases (
 id INT AUTO_INCREMENT PRIMARY KEY, reserve_entry_id INT NOT NULL, control_account_id INT NOT NULL,
 release_date DATE NOT NULL, amount DECIMAL(16,2) NOT NULL, reason VARCHAR(255) NOT NULL,
 created_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_release_entry(reserve_entry_id), KEY idx_release_account_date(control_account_id,release_date),
 FOREIGN KEY(reserve_entry_id) REFERENCES control_account_entries(id),
 FOREIGN KEY(control_account_id) REFERENCES control_accounts(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE control_account_entries
 ADD COLUMN IF NOT EXISTS source_table VARCHAR(50) NULL,
 ADD COLUMN IF NOT EXISTS source_id INT NULL,
 ADD COLUMN IF NOT EXISTS voided_at DATETIME NULL,
 ADD COLUMN IF NOT EXISTS voided_by INT NULL,
 ADD COLUMN IF NOT EXISTS void_reason VARCHAR(255) NULL;
ALTER TABLE budget_transactions ADD COLUMN IF NOT EXISTS ledger_entry_id INT NULL,
 ADD COLUMN IF NOT EXISTS cancelled_at DATETIME NULL;
ALTER TABLE budget_disbursements ADD COLUMN IF NOT EXISTS ledger_entry_id INT NULL,
 ADD COLUMN IF NOT EXISTS cancelled_at DATETIME NULL;
ALTER TABLE payment_vouchers ADD COLUMN IF NOT EXISTS control_account_id INT NULL, ADD COLUMN IF NOT EXISTS expense_category VARCHAR(3) NULL, ADD COLUMN IF NOT EXISTS cancelled_at DATETIME NULL, ADD COLUMN IF NOT EXISTS cancelled_by INT NULL, ADD COLUMN IF NOT EXISTS cancel_reason VARCHAR(255) NULL;
ALTER TABLE budget_advances ADD COLUMN IF NOT EXISTS control_account_id INT NULL, ADD COLUMN IF NOT EXISTS expense_category VARCHAR(3) NULL, ADD COLUMN IF NOT EXISTS cancelled_at DATETIME NULL, ADD COLUMN IF NOT EXISTS cancelled_by INT NULL, ADD COLUMN IF NOT EXISTS cancel_reason VARCHAR(255) NULL;
ALTER TABLE po_reservations ADD COLUMN IF NOT EXISTS control_account_id INT NULL, ADD COLUMN IF NOT EXISTS expense_category VARCHAR(3) NULL, ADD COLUMN IF NOT EXISTS cancelled_at DATETIME NULL, ADD COLUMN IF NOT EXISTS cancelled_by INT NULL, ADD COLUMN IF NOT EXISTS cancel_reason VARCHAR(255) NULL;
ALTER TABLE budget_advances ADD COLUMN IF NOT EXISTS settled_amount DECIMAL(16,2) NULL, ADD COLUMN IF NOT EXISTS settled_date DATE NULL;
ALTER TABLE po_reservations ADD COLUMN IF NOT EXISTS released_date DATE NULL;
ALTER TABLE budget_transfers ADD COLUMN IF NOT EXISTS cancelled_at DATETIME NULL, ADD COLUMN IF NOT EXISTS cancelled_by INT NULL, ADD COLUMN IF NOT EXISTS cancel_reason VARCHAR(255) NULL;
ALTER TABLE control_accounts ADD COLUMN IF NOT EXISTS cancelled_at DATETIME NULL, ADD COLUMN IF NOT EXISTS cancelled_by INT NULL, ADD COLUMN IF NOT EXISTS cancel_reason VARCHAR(255) NULL;
DELIMITER $$
CREATE OR REPLACE PROCEDURE rpbs_assert_open(IN p_unit INT, IN p_year INT, IN p_date DATE)
BEGIN
 DECLARE v_closed INT DEFAULT 0;
 INSERT IGNORE INTO fiscal_periods(unit_id,fiscal_year,period_month) VALUES(p_unit,p_year,0);
 SELECT closed INTO v_closed FROM fiscal_periods WHERE unit_id=p_unit AND fiscal_year=p_year AND period_month=0 FOR UPDATE;
 IF v_closed=1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Fiscal year is closed; reopen with a reason before changing records'; END IF;
 IF p_date IS NOT NULL THEN
  INSERT IGNORE INTO fiscal_periods(unit_id,fiscal_year,period_month) VALUES(p_unit,p_year,MONTH(p_date));
  SELECT closed INTO v_closed FROM fiscal_periods WHERE unit_id=p_unit AND fiscal_year=p_year AND period_month=MONTH(p_date) FOR UPDATE;
 ELSE
  SELECT COALESCE(MAX(closed),0) INTO v_closed FROM fiscal_periods WHERE unit_id=p_unit AND fiscal_year=p_year;
 END IF;
 IF v_closed=1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Fiscal period is closed; reopen with a reason before changing records'; END IF;
END$$
DELIMITER ;
