CREATE OR REPLACE TRIGGER rpbs_immutable_document_snapshots_delete BEFORE DELETE ON `document_snapshots` FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Audit records and issued documents are immutable';
CREATE OR REPLACE VIEW active_control_entries AS SELECT e.* FROM control_account_entries e WHERE e.voided_at IS NULL UNION ALL SELECT -r.id,e.control_account_id,r.release_date,e.gfmis_code,e.activity_code,e.disbursement_no,e.entry_type,-r.amount,e.spending_unit_id,e.expense_category,r.reason,r.created_by,r.created_at,NULL,'reservation_releases',r.id,NULL,NULL,NULL FROM reservation_releases r JOIN control_account_entries e ON e.id=r.reserve_entry_id WHERE e.voided_at IS NULL;
